{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING AS WITH sales_1p AS ( SELECT ORDER_TIMESTAMP AS DAY, \'Amazon_1P\' AS MARKETPLACE, REGION AS GEO, PRODUCT_ID AS ASIN, MAX(MAPPED_PRODUCT_NAME) AS PRODUCT_NAME, MAX(CURRENCY) AS CURRENCY, SUM(QUANTITY) AS QUANTITY, SUM(LINE_ITEM_SALES) AS SALES_LOCAL, SUM(TOTAL_SECONDARY_SALES) AS SECONDARY_SALES_LOCAL FROM VAHDAM_DB.MAPLEMONK.VAHDAM_DB_Amazon_Vendor_central_Sales_consolidated WHERE IS_REFUND = 0 AND PRODUCT_ID IS NOT NULL GROUP BY ORDER_TIMESTAMP, REGION, PRODUCT_ID ), spend_1p AS ( SELECT DATE AS DAY, \'Amazon_1P\' AS MARKETPLACE, GEO, ASIN, MAX(CURRENCY) AS CURRENCY, SUM(SPEND) AS SPEND_LOCAL, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS FROM VAHDAM_DB.MAPLEMONK.vendor_central_marketing_consolidated_new WHERE ASIN IS NOT NULL GROUP BY DATE, GEO, ASIN ), combined_1p AS ( SELECT COALESCE(sa.DAY, sp.DAY) AS DAY, \'Amazon_1P\' AS MARKETPLACE, COALESCE(sa.GEO, sp.GEO) AS GEO, COALESCE(sa.ASIN, sp.ASIN) AS ASIN, sa.PRODUCT_NAME AS PRODUCT_NAME, COALESCE(sa.CURRENCY, sp.CURRENCY) AS CURRENCY, COALESCE(sa.QUANTITY, 0) AS QUANTITY, COALESCE(sa.SALES_LOCAL, 0) AS SALES_LOCAL, COALESCE(sa.SECONDARY_SALES_LOCAL,0) AS SECONDARY_SALES_LOCAL, COALESCE(sp.SPEND_LOCAL, 0) AS SPEND_LOCAL, NULL::FLOAT AS SESSIONS, COALESCE(sp.IMPRESSIONS, 0) AS IMPRESSIONS, COALESCE(sp.CLICKS, 0) AS CLICKS, 0::FLOAT AS GOOGLE_SPEND_LOCAL FROM sales_1p sa FULL OUTER JOIN spend_1p sp ON sa.DAY = sp.DAY AND sa.GEO = sp.GEO AND sa.ASIN = sp.ASIN ), gads_3p AS ( SELECT \"segments.date\" AS DAY, CASE WHEN \"campaign.name\" ILIKE \'%amazon.com%\' THEN \'USA\' WHEN \"campaign.name\" ILIKE \'%amazon.ca%\' THEN \'CA\' WHEN \"campaign.name\" ILIKE \'%amazon.co.uk%\' THEN \'UK\' WHEN \"campaign.name\" ILIKE \'%amazon.de%\' THEN \'DE\' WHEN \"campaign.name\" ILIKE \'%amazon.in%\' THEN \'IN\' END AS GEO, REGEXP_SUBSTR(\"campaign.name\", \'B0[A-Z0-9]{8}\') AS ASIN, SUM(\"metrics.cost_micros\")/1000000 AS GOOGLE_SPEND_LOCAL FROM VAHDAM_DB.MAPLEMONK.US_AMZ_GADS_CAMPAIGN_DATA GROUP BY 1, 2, 3 HAVING ASIN IS NOT NULL AND GEO IS NOT NULL ), combined_3p AS ( SELECT m.DATE AS DAY, \'Amazon_3P\' AS MARKETPLACE, m.REGION AS GEO, m.ASIN, MAX(m.PRODUCTNAME) AS PRODUCT_NAME, MAX(CASE WHEN m.CURRENCY IS NOT NULL AND m.CURRENCY != \'\' THEN m.CURRENCY END) AS CURRENCY, SUM(m.QUANTITY) AS QUANTITY, SUM(m.SALES_USD) AS SALES_LOCAL, SUM(m.SALES_USD) AS SECONDARY_SALES_LOCAL, SUM(m.SPEND) AS SPEND_LOCAL, SUM(m.SESSIONS) AS SESSIONS, SUM(m.IMPRESSIONS) AS IMPRESSIONS, SUM(m.CLICKS) AS CLICKS, MAX(g.GOOGLE_SPEND_LOCAL) AS GOOGLE_SPEND_LOCAL FROM VAHDAM_DB.MAPLEMONK.VAHDAM_DB_AMAZONADS_MARKETING_CONSOLIDATED m LEFT JOIN gads_3p g ON g.DAY = m.DATE AND g.GEO = m.REGION AND g.ASIN = m.ASIN WHERE m.ASIN IS NOT NULL GROUP BY m.DATE, m.REGION, m.ASIN ) SELECT DAY, ASIN, PRODUCT_NAME, MARKETPLACE, GEO, CURRENCY, ROUND(QUANTITY, 2) AS QUANTITY, ROUND(SALES_LOCAL, 2) AS SALES, ROUND(SECONDARY_SALES_LOCAL, 2) AS SECONDARY_SALES, ROUND(SPEND_LOCAL, 2) AS SPEND, ROUND(GOOGLE_SPEND_LOCAL, 2) AS GOOGLE_SPEND, SESSIONS, IMPRESSIONS, CLICKS, CASE WHEN SESSIONS > 0 THEN ROUND(QUANTITY / SESSIONS, 4) END AS CONVERSION_RATE, CASE WHEN SALES_LOCAL > 0 THEN ROUND(SPEND_LOCAL / SALES_LOCAL, 4) END AS ACOS FROM ( SELECT * FROM combined_1p UNION ALL SELECT * FROM combined_3p ) ORDER BY DAY DESC, MARKETPLACE, GEO, SALES DESC NULLS LAST; create or replace table vahdam_db.maplemonk.VAHDAM_AMAZON_MARKETING as WITH mkt_1p AS ( SELECT DATE AS DAY, \'Amazon_1P\' AS MARKETPLACE, GEO, ASIN, CURRENCY, CAMPAIGN_TYPE, CAMPAIGNID, CAMPAIGNNAME, CAMPAIGNSTATUS, ADGROUPID, ADGROUPNAME, KEYWORDTEXT, TARGETINGEXPRESSION, TARGETINGTEXT, ADID, PROFILEID, SPEND, SALES AS AD_SALES, IMPRESSIONS, CLICKS, CONVERSIONS, CONVERSIONSSAMESKU, SALESSAMESKU, NEWTOBRANDORDERS, NEWTOBRANDSALES, NEWTOBRANDUNITS, NULL::VARCHAR AS PRODUCT_NAME, NULL::VARCHAR AS BRAND, NULL::VARCHAR AS PRODUCT_CATEGORY, NULL::FLOAT AS OTHERSKUSALES, NULL::FLOAT AS CONVERSIONSOTHERSKU FROM VAHDAM_DB.MAPLEMONK.vendor_central_marketing_consolidated_new WHERE ASIN IS NOT NULL ), mkt_3p AS ( SELECT DATE AS DAY, \'Amazon_3P\' AS MARKETPLACE, REGION AS GEO, ASIN, CURRENCY, CAMPAIGN_TYPE, CAMPAIGNID::VARCHAR AS CAMPAIGNID, CAMPAIGNNAME, CAMPAIGNSTATUS, ADGROUPID::VARCHAR AS ADGROUPID, ADGROUPNAME, KEYWORDTEXT, TARGETINGEXPRESSION, TARGETINGTEXT, ADID::VARCHAR AS ADID, PROFILEID::VARCHAR AS PROFILEID, SPEND, SALES AS AD_SALES, IMPRESSIONS, CLICKS, CONVERSIONS, CONVERSIONSSAMESKU, SALESSAMESKU, NEWTOBRANDORDERS, NEWTOBRANDSALES, NEWTOBRANDUNITS, PRODUCTNAME AS PRODUCT_NAME, BRAND, PRODUCTCATEGORY AS PRODUCT_CATEGORY, OTHERSKUSALES, CONVERSIONSOTHERSKU FROM VAHDAM_DB.MAPLEMONK.VAHDAM_DB_AMAZONADS_MARKETING_CONSOLIDATED WHERE ASIN IS NOT NULL ) SELECT DAY, ASIN, PRODUCT_NAME, BRAND, PRODUCT_CATEGORY, MARKETPLACE, GEO, CURRENCY, CAMPAIGN_TYPE, CAMPAIGNID, CAMPAIGNNAME, CAMPAIGNSTATUS, ADGROUPID, ADGROUPNAME, KEYWORDTEXT, TARGETINGEXPRESSION, TARGETINGTEXT, ADID, PROFILEID, ROUND(SPEND, 2) AS SPEND, ROUND(AD_SALES, 2) AS AD_SALES, IMPRESSIONS, CLICKS, CONVERSIONS, CONVERSIONSSAMESKU, ROUND(SALESSAMESKU, 2) AS SALESSAMESKU, CONVERSIONSOTHERSKU, ROUND(OTHERSKUSALES, 2) AS OTHERSKUSALES, NEWTOBRANDORDERS, ROUND(NEWTOBRANDSALES, 2) AS NEWTOBRANDSALES, NEWTOBRANDUNITS, CASE WHEN IMPRESSIONS > 0 THEN ROUND(CLICKS / IMPRESSIONS, 4) END AS CTR, CASE WHEN CLICKS > 0 THEN ROUND(SPEND / CLICKS, 4) END AS CPC, CASE WHEN AD_SALES > 0 THEN ROUND(SPEND / AD_SALES, 4) END AS ACOS_AD, CASE WHEN SPEND > 0 THEN ROUND(AD_SALES / SPEND, 2) END AS ROAS, CASE WHEN CLICKS > 0 THEN ROUND(CONVERSIONS / CLICKS, 4) END AS CONV_RATE FROM (SELECT * FROM mkt_1p UNION ALL SELECT * FROM mkt_3p) ORDER BY DAY DESC, MARKETPLACE, GEO, ASIN, SPEND DESC NULLS LAST;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from VAHDAM_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            